/* @autogenerated */
import { UserGroupMembershipRepository } from 'app/features/access/user-group-membership/repository/user-group-membership-repository.service';
import { User } from 'app/features/identity/user/model/user.model';
import { UserFederatedIdentityRepository } from 'app/features/identity/user-federated-identity/repository/user-federated-identity-repository.service';
import { UserRoleAssignmentRepository } from 'app/features/access/user-role-assignment/repository/user-role-assignment-repository.service';
import { BaseDocumentAction } from 'app/shared/toolkit/action/base-document-action';
import { UserRepository } from 'app/features/identity/user/repository/user-repository.service';
import { DocumentDefinition } from 'app/shared/toolkit/entity-document/document.model';
import { Component, inject } from '@angular/core';

/** Documento profile (plantilla `identity/user/profile`). */
@Component({
  selector: 'user-view-profile-action',
  standalone: false,
  templateUrl: './user-view-profile-action.component.html',
})
export class UserViewProfileActionComponent extends BaseDocumentAction<User> {
  readonly name = 'profile';
  protected readonly scope = 'identity/user';
  protected readonly repository = inject(UserRepository);
  private readonly userFederatedIdentityRepository = inject(UserFederatedIdentityRepository);
  private readonly userRoleAssignmentRepository = inject(UserRoleAssignmentRepository);
  private readonly userGroupMembershipRepository = inject(UserGroupMembershipRepository);

  readonly definition: DocumentDefinition<User> = {
    template: 'identity/user/profile',
    fileName: (item) => `user-${item.name ?? ''}`,
    data: (item) =>
      this.repository.resolve(item.uid, ['tenant'], {
        identities: this.userFederatedIdentityRepository.children('user', ['login-provider']),
        roles: this.userRoleAssignmentRepository.children('user', ['resource-server', 'oauth-client']),
        groups: this.userGroupMembershipRepository.children('user', ['resource-server', 'oauth-client']),
      }),
  };
}
